  for(const[label,value]of values){const row=append(provenance,'div');append(row,'dt',label);const dd=append(row,'dd',value);if(['الملف','الكتاب'].includes(label))dd.dir='auto';if(label==='بصمة الملف'){dd.dir='ltr';dd.style.fontSize='12px';dd.style.overflowWrap='anywhere';}}
