  append(box,'p',`الفحص الأساسي مقارنة بالتشغيل السابق: ${manifest.changeReasons.map(r=>reasons[r]||r).join('، ')}. مقارنة النسخ لها سياق وبصمات مستقلة في تقريرها.`,'manifest-note');
  const details=append(box,'details');append(details,'summary','بصمات التشغيل وسجل الإعادة');for(const[key,label]of [['inputSha256','بصمة المدخلات'],['outputSha256','بصمة نتيجة الفحص'],['contextSha256','بصمة السياق']]){append(details,'strong',label);const hash=append(details,'p',manifest.fingerprints[key],'manifest-hash');hash.dir='ltr';}append(details,'p','البصمات تربط البيانات، ولا تثبت صحة المعنى أو هوية مراجع. بصمة نتيجة الفحص قبل إضافة القرارات ومقارنة النسخ والتصدير.','manifest-note');
